int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int ret = -EINVAL;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return ret;

    if (nlh->nlmsg_type >= MAX_DIAG_TYPE)
        return ret;

    if (!atomic_read(&diag_handlers[nlh->nlmsg_type].refcnt))
        return ret;

    if (try_module_get(diag_handlers[nlh->nlmsg_type].owner) != 0) {
        struct diag_handler *handler = &diag_handlers[nlh->nlmsg_type];
        spin_lock(&handler->lock);
        if (handler->dump) {
            ret = handler->dump(skb, nlh);
        }
        spin_unlock(&handler->lock);
        module_put(handler->owner);
    }

    return ret;
}

