int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int family;
    int (*dump_func)(struct sk_buff *, struct nlmsghdr *);
    struct diag_handler *handler;

    if (nlh->nlmsg_len < NLMSG_HDRLEN) {
        return -EINVAL;
    }

    family = ((struct sock_diag_req *)NLMSG_DATA(nlh))->sdiag_family;

    if (family < 0 || family >= AF_MAX) {
        return -EAFNOSUPPORT;
    }

    handler = get_diag_handler(family);
    if (!handler || !handler->dump) {
        return -ENOENT;
    }

    mutex_lock(&handler->mutex);

    dump_func = handler->dump;
    int ret = dump_func(skb, nlh);

    mutex_unlock(&handler->mutex);

    return ret;
}

int process_diag_message(struct sk_buff *skb, struct nlmsghdr *nlh) {
    struct sock_diag_handler *handler;
    int family;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return -EINVAL;

    family = *(int *)NLMSG_DATA(nlh);
    if (family < 0 || family >= AF_MAX)
        return -EINVAL;

    handler = sock_diag_lock_handler(family);
    if (!handler)
        return -ENOENT;

    skb->sk = handler->sk;
    skb->cb[0] = 0;

    if (handler->dump) {
        int err = handler->dump(skb, nlh);
        if (err < 0)
            return err;
    }

    sock_diag_unlock_handler(family);
    return 0;
}

int process_sock_diag_msg(struct sk_buff *skb, struct nlmsghdr *nlh) {
    int family;
    int err = -EINVAL;

    if (nlh->nlmsg_len < NLMSG_HDRLEN)
        return -EINVAL;

    family = ((struct sock_diag_req *)NLMSG_DATA(nlh))->sdiag_family;
    if (family < AF_MIN || family > AF_MAX)
        return -EAFNOSUPPORT;

    if (!try_module_get(sock_diag_handlers[family].owner))
        return -ENOENT;

    err = sock_diag_handlers[family].dump(skb, nlh);

    module_put(sock_diag_handlers[family].owner);
    return err;
}
